	["Features/AssetBrowser.lua"] = [======[
-- AssetBrowser is the Asset Explorer, a window of its own opened from the
-- Crafting tab. It shows every item in the game's assets (AssetDictionary):
--
--   * The left side lists them by type, then level, narrowed by the search
--     box and the ALL / OWNED / <type> chips. A thin bar under each row is
--     its best DMG / DEF / DEX against its type.
--   * The right side (AssetDetail) is the one picked: type, level, trade
--     lock, how many you have, its stats with their rank, buy and sell
--     price, the recipe that makes it and the mobs that drop it, and the
--     recipes that use it.
--   * DUMP DATABASE, across the bottom, writes every item, recipe and mob
--     the script can read to a JSON file (DatabaseDump).
return {
    Name = "AssetBrowser",
    IsFeature = true,
    Dependencies = {"Runtime", "Components", "BrowserShell", "DetailKit", "SmithingRecipes", "AssetDictionary", "AssetDetail", "DatabaseDump"},

    Start = function(Context)
        local UI = Context.UI
        local UIRef = Context.UIRef
        local Kit = Context.DetailKit
        local Recipes = Context.SmithingRecipes
        local Assets = Context.AssetDictionary
        local Detail = Context.AssetDetail
        local Dump = Context.DatabaseDump

        --// The inventory is read again this often while open.
        local REFRESH_INTERVAL = 2
        local ALL = "ALL"
        local OWNED = "OWNED"

        local Browser = {
            Name = "AssetBrowser",
            IsFeature = true,
            S = {
                LastRefresh = 0,
                --// Item -> count, read once per refresh.
                Stock = {},
            },
        }

        local S = Browser.S

        local function MatchesChip(Entry, Key)
            if Key == OWNED then
                return (S.Stock[Entry.Name] or 0) > 0
            end

            return Key == ALL or Key == nil or Entry.Type == Key
        end

        local function GetChips(Entries)
            local Counts, Types = {}, {}
            local Owned = 0

            for _, Entry in ipairs(Entries) do
                if not Counts[Entry.Type] then
                    Counts[Entry.Type] = 0
                    table.insert(Types, Entry.Type)
                end

                Counts[Entry.Type] += 1

                if (S.Stock[Entry.Name] or 0) > 0 then
                    Owned += 1
                end
            end

            table.sort(Types)

            local Chips = {
                { Key = ALL, Text = string.format("ALL  %d", #Entries) },
                { Key = OWNED, Text = string.format("OWNED  %d", Owned) },
            }

            for _, Type in ipairs(Types) do
                table.insert(Chips, { Key = Type, Text = string.format("%s  %d", string.upper(Type), Counts[Type]) })
            end

            return Chips
        end

        local function DescribeRow(Entry)
            local Theme = UI.Theme
            local Have = S.Stock[Entry.Name] or 0

            return {
                Info = Have > 0 and Entry.Summary .. "  ·  ×" .. Kit.FormatNumber(Have) or Entry.Summary,
                InfoColor = Have > 0 and Kit.GOOD_COLOR or nil,
                Accent = Entry.Flags.Bound and Theme.Warning or Theme.Cyan,
                Bar = Entry.Power,
                BarColor = Theme.Cyan,
            }
        end

        --// Name, type and every text value, so "fire" finds fire swords.
        local function MatchesSearch(Entry, Query)
            if string.find(string.lower(Entry.Name), Query, 1, true)
                or string.find(string.lower(Entry.Type), Query, 1, true)
            then
                return true
            end

            for _, Stat in ipairs(Entry.Stats) do
                if type(Stat.Value) == "string" and string.find(string.lower(Stat.Value), Query, 1, true) then
                    return true
                end
            end

            return false
        end

        local Shell = Context.BrowserShell.New({
            Title = "ASSET EXPLORER",
            Subtitle = "Every item  //  stats, price, where it comes from and goes",
            Width = 760,
            Height = 520,
            MinWidth = 580,
            MinHeight = 380,
            SearchPlaceholder = "SEARCH ITEM, TYPE OR VALUE...",
            ReloadText = "↻  RELOAD",
            OnReload = function()
                Browser:Reload()
            end,
            GetItems = function()
                return Assets:GetAll()
            end,
            GetChips = GetChips,
            MatchesChip = MatchesChip,
            MatchesSearch = MatchesSearch,
            DescribeRow = DescribeRow,
            GetSelected = function()
                return Detail:GetSelected()
            end,
            OnSelect = function(Name)
                Browser:Select(Name)
            end,
            GetEmptyText = function(Count)
                if Count == 0 then
                    return Assets.S.Error and "Assets unavailable" or "No items found"
                end

                return "No items match the filters"
            end,
            FooterText = "DUMP DATABASE",
            OnFooter = function()
                Browser:Dump()
            end,
        })

        function Browser:Refresh()
            if not Shell:IsOpen() then
                return
            end

            S.LastRefresh = os.clock()
            S.Stock = Recipes:GetInventory()
            Shell:RefreshList()
            Detail:Refresh(S.Stock)
        end

        function Browser:Select(Name)
            S.Stock = Recipes:GetInventory()
            Detail:Select(Name, S.Stock)
            Browser:Refresh()
        end

        --// Writes every item, recipe and mob to a JSON file, for the site's
        --// database to be built from (DatabaseDump).
        function Browser:Dump()
            Dump:Dump()
        end

        --// Reads the assets again, keeping the pick.
        function Browser:Reload()
            Assets:Load()

            if not Shell.Built then
                return
            end

            Shell:ResetRows()

            local Selected = Detail:GetSelected()

            if not Selected or not Assets:Get(Selected) then
                local First = Assets:GetAll()[1]
                Selected = First and First.Name or nil
            end

            Browser:Select(Selected)
        end

        function Browser:Open()
            if not Shell:Open() then
                return
            end

            Detail:Build(Shell.DetailScroll)

            if not Assets.S.Loaded then
                Browser:Reload()
            else
                S.Stock = Recipes:GetInventory()
                Detail:Rebuild(S.Stock)
                Browser:Refresh()
            end
        end

        function Browser:Toggle()
            if Shell:IsOpen() then
                Shell:Close()
            else
                Browser:Open()
            end
        end

        function Browser:Update()
            if Shell:IsOpen() and os.clock() - S.LastRefresh >= REFRESH_INTERVAL then
                Browser:Refresh()
            end
        end

        --// Under Open Recipe Browser on the Crafting tab, which AutoSmithing
        --// builds late too (it starts first, so its controls come first).
        function Browser:BuildLateUI()
            if UIRef.CraftSection then
                UIRef.CraftSection:AddButton{
                    Name = "Open Asset Explorer",
                    Callback = function()
                        Browser:Toggle()
                    end,
                }
            end
        end

        return Browser
    end,
}
]======],
	["Features/AssetDetail.lua"] = [======[
-- AssetDetail is the right side of the Asset Explorer (AssetBrowser): the
-- one item picked, laid out to be read at a glance:
--
--   * Its name, type, level, whether it can be traded, how it is locked
--     (pass, badge, group, event currency), and how many you have.
--   * DMG / DEF / DEX in big numbers with their rank among its type.
--   * VALUE: what the shop asks for it and pays for it.
--   * HOW TO GET: the recipe that makes it (materials against your
--     inventory) and the mobs seen dropping it, with the chance per kill.
--   * USED IN: the recipes that need it.
--   * Every number as a bar against the best of its type, its other values
--     as tags, its status effect, and COPY NAME / OPEN RECIPE.
return {
    Name = "AssetDetail",
    Dependencies = {"Runtime", "Floating", "DetailKit", "AssetDictionary", "MobDictionary"},

    Start = function(Context)
        local UI = Context.UI
        local Floating = Context.Floating
        local Kit = Context.DetailKit
        local Assets = Context.AssetDictionary
        local Mobs = Context.MobDictionary

        local Label, Button, ClearChildren = Floating.Label, Floating.Button, Floating.ClearChildren
        local FormatNumber, FormatPercent = Kit.FormatNumber, Kit.FormatPercent
        local Card, Heading, Note, Badge, Strip, Track, BarRow = Kit.Card, Kit.Heading, Kit.Note, Kit.Badge, Kit.Strip, Kit.Track, Kit.BarRow

        local STAT_BAR_HEIGHT = 30
        local LINE_HEIGHT = 16
        local POWER_KEYS = { "DMG", "DEF", "DEX" }
        local STAT_COLORS = { DMG = "Danger", DEF = "Cyan", DEX = "Warning" }

        local Detail = {
            Name = "AssetDetail",
            S = {
                Selected = nil,
                --// Inventory count, Luck and known drop sources the detail
                --// was built with; a change rebuilds it.
                Signature = nil,
            },
        }

        local S = Detail.S
        local Theme, Scroll

        local function GetStatColor(Key)
            local ThemeKey = STAT_COLORS[Key]
            return ThemeKey and Theme[ThemeKey] or Theme.TextSecondary
        end

        --// "1,200 COL", or the event currency it is bought with.
        local function FormatPrice(Entry, Amount)
            return FormatNumber(Amount) .. " " .. string.upper(Entry.EventCurrency or "Col")
        end

        --// A plain line of text, Color optional.
        local function Line(Parent, Text, Order, Color, Bold)
            return Label(Parent, Text, 10, {
                Size = UDim2.new(1, 0, 0, LINE_HEIGHT),
                TextColor3 = Color or Theme.Text,
                Font = Bold and Floating.Fonts.Bold or Floating.Fonts.Regular,
                LayoutOrder = Order,
            })
        end

        ------------------------------------------------------------------------
        --// Sections
        ------------------------------------------------------------------------

        local function BuildHero(Entry, Have, Order)
            local Hero = Card(Scroll, Order)

            Label(Hero, string.upper(Entry.Name), 16, {
                Font = Floating.Fonts.Bold,
                TextColor3 = Theme.Text,
                LayoutOrder = 1,
            })

            local Badges = Strip(Hero, 18, 2, true)
            local Flags = Entry.Flags
            local Level, LevelKind = Assets.GetLevel(Entry)
            local Index = 0

            local function Add(Text, Color)
                Index += 1
                Badge(Badges, Text, Color, Index)
            end

            Add(string.upper(Entry.Type), Theme.Cyan)

            if Level then
                Add(LevelKind .. " " .. FormatNumber(Level), Theme.TextSecondary)
            end

            Add(Flags.Bound and "BOUND" or "TRADEABLE", Flags.Bound and Theme.Warning or Kit.GOOD_COLOR)

            if Flags.Unobtainable then
                Add("UNOBTAINABLE", Theme.Danger)
            end

            if Flags.Pass then
                Add("GAME PASS", Theme.Warning)
            end

            if Flags.Badge then
                Add("BADGE", Theme.Warning)
            end

            if Flags.Group then
                Add("GROUP", Theme.Warning)
            end

            if Entry.EventCurrency then
                Add("EVENT  " .. string.upper(Entry.EventCurrency), Theme.Warning)
            end

            if Entry.Status then
                Add("☠  " .. string.upper(Entry.Status.Name), Theme.Warning)
            end

            Add(Have > 0 and ("HAVE  " .. FormatNumber(Have)) or "NOT OWNED", Have > 0 and Kit.GOOD_COLOR or Theme.TextMuted)
        end

        --// DMG / DEF / DEX in big type, or its worth when it has none.
        local function BuildTiles(Entry, Order)
            local Tiles = {}

            for _, Key in ipairs(POWER_KEYS) do
                local Value = Assets.GetStat(Entry, Key)

                if type(Value) == "number" then
                    local _, Rank, Total = Assets.GetScale(Entry.Type, Key, Value)

                    table.insert(Tiles, {
                        Value = FormatNumber(Value),
                        Label = Key,
                        Note = Rank and string.format("#%d OF %d", Rank, Total) or nil,
                        Color = GetStatColor(Key),
                    })
                end
            end

            if #Tiles == 0 and Entry.Worth then
                table.insert(Tiles, {
                    Value = FormatPrice(Entry, Entry.Worth),
                    Label = "WORTH",
                    Color = Theme.Cyan,
                })
            end

            Kit.Tiles(Scroll, Order, Tiles)
        end

        local function BuildValue(Entry, Order)
            if not Entry.Worth then
                return
            end

            local ValueCard = Card(Scroll, Order)
            Heading(ValueCard, "VALUE", 0)

            if Entry.Flags.Unobtainable then
                Line(ValueCard, "BUY  ·  not sold in shops", 1, Theme.TextMuted)
            else
                Line(ValueCard, "BUY  ·  " .. FormatPrice(Entry, Entry.Worth), 1, Theme.Cyan, true)
            end

            local Sell = Assets.GetSellPrice(Entry)

            if Sell then
                Line(ValueCard, string.format(
                    "SELL  ·  %s COL   (%s with the Agility pass)",
                    FormatNumber(Sell.Normal), FormatNumber(Sell.Agility)
                ), 2, Kit.GOOD_COLOR, true)
            else
                Line(ValueCard, "SELL  ·  the shop does not buy it", 2, Theme.TextMuted)
            end
        end

        --// The recipe: skill, and each material against the inventory.
        local function BuildRecipe(Parent, Recipe, Stock, Order)
            local Skill = Context.SmithingRecipes:GetSkill()
            local Locked = Recipe.Skill > Skill

            Line(Parent, string.format(
                "CRAFTED  ·  SMITHING SKILL %s  (YOURS %s)",
                FormatNumber(Recipe.Skill), FormatNumber(Skill)
            ), Order, Locked and Theme.Danger or Theme.Cyan, true)

            for Index, Material in ipairs(Recipe.Materials) do
                local Have = Stock[Material.Name] or 0

                Line(Parent, string.format(
                    "    %s   %s / %s",
                    Material.Name, FormatNumber(Have), FormatNumber(Material.Amount)
                ), Order + Index, Have >= Material.Amount and Theme.Text or Theme.Warning)
            end
        end

        local function BuildSources(Entry, Stock, Order)
            local Recipe = Assets:GetRecipe(Entry.Name)
            local Sources = Assets:GetDroppedBy(Entry.Name)
            local SourceCard = Card(Scroll, Order)

            Heading(SourceCard, "HOW TO GET", 0)

            if Recipe then
                BuildRecipe(SourceCard, Recipe, Stock, 1)
            end

            for Index, Source in ipairs(Sources) do
                local Holder = BarRow(
                    SourceCard, STAT_BAR_HEIGHT, 100 + Index,
                    "DROPPED BY  " .. string.upper(Source.Mob),
                    FormatPercent(Source.Chance) .. " / KILL",
                    Source.Chance > 0 and Theme.Cyan or Theme.Danger
                )

                Track(Holder, 18, { { Fraction = Source.Chance, Color = Theme.Cyan } })
            end

            if not Recipe and #Sources == 0 then
                Note(SourceCard, Entry.Flags.Unobtainable
                    and "No recipe makes it and no known mob drops it."
                    or "No recipe makes it and no known mob drops it. It may be sold in a shop.", 1)
            end

            Note(SourceCard, "Drops are known for mobs that have been in the server, now or in an earlier run (Mob Dictionary).", 999)
        end

        local function BuildUses(Entry, Order)
            local Uses = Assets:GetUses(Entry.Name)

            if #Uses == 0 then
                return
            end

            local UsesCard = Card(Scroll, Order)
            Heading(UsesCard, string.format("USED IN  %d RECIPE%s", #Uses, #Uses == 1 and "" or "S"), 0)

            for Index, Use in ipairs(Uses) do
                Line(UsesCard, string.format(
                    "%s   ×%s   ·   SKILL %s",
                    string.upper(Use.Recipe.Name), FormatNumber(Use.Amount), FormatNumber(Use.Recipe.Skill)
                ), Index)
            end
        end

        --// Every number, and its worth, against the best of its type.
        local function BuildBars(Entry, Order)
            local Rows = {}

            for _, Stat in ipairs(Entry.Stats) do
                if Stat.Numeric then
                    table.insert(Rows, { Key = Stat.Key, Label = Stat.Label, Value = Stat.Value })
                end
            end

            if Entry.Worth then
                table.insert(Rows, { Key = "Worth", Label = "WORTH", Value = Entry.Worth })
            end

            if #Rows == 0 then
                return
            end

            local BarsCard = Card(Scroll, Order)
            Heading(BarsCard, "COMPARED TO THE BEST " .. string.upper(Entry.Type), 0)

            for Index, Row in ipairs(Rows) do
                local Fraction, Rank, Total = Assets.GetScale(Entry.Type, Row.Key, Row.Value)
                local Value = FormatNumber(Row.Value) .. (Rank and string.format("   #%d/%d", Rank, Total) or "")
                local Holder = BarRow(BarsCard, STAT_BAR_HEIGHT, Index, Row.Label, Value)
                Track(Holder, 18, { { Fraction = Fraction, Color = GetStatColor(Row.Key) } })
            end
        end

        local function BuildTraits(Entry, Order)
            local Traits = {}

            for _, Stat in ipairs(Entry.Stats) do
                if not Stat.Numeric then
                    table.insert(Traits, Stat)
                end
            end

            if #Traits > 0 then
                local TraitsCard = Card(Scroll, Order)
                Heading(TraitsCard, "TRAITS", 0)
                Kit.Tags(TraitsCard, Traits, Theme.TextSecondary, 1)
            end

            if Entry.Status then
                local StatusCard = Card(Scroll, Order + 1)
                Heading(StatusCard, "STATUS EFFECT", 0)
                Line(StatusCard, "☠  " .. string.upper(Entry.Status.Name), 1, Theme.Warning, true)

                if #Entry.Status.Props > 0 then
                    Kit.Tags(StatusCard, Entry.Status.Props, Theme.Warning, 2)
                end
            end
        end

        local function BuildActions(Entry, Order)
            local Row = Strip(Scroll, 28, Order)
            Row.Size = UDim2.new(1, -6, 0, 28)

            local HasRecipe = Assets:GetRecipe(Entry.Name) ~= nil
            local CopyButton = Button(Row, "COPY NAME", Theme.TextMuted, {
                Size = UDim2.new(HasRecipe and 0.5 or 1, HasRecipe and -2 or 0, 1, 0),
                LayoutOrder = 1,
            })

            CopyButton.Activated:Connect(function()
                local Copied = Floating.CopyText(Entry.Name)
                Context.NotifyAction("Asset Explorer", Copied and "Name copied" or "No clipboard here")
            end)

            if HasRecipe then
                local RecipeButton = Button(Row, "OPEN RECIPE  ›", Theme.Cyan, {
                    Size = UDim2.new(0.5, -2, 1, 0),
                    LayoutOrder = 2,
                })

                RecipeButton.Activated:Connect(function()
                    local Browser = Context.SmithingBrowser

                    if Browser then
                        Browser:Open()
                        Browser:Select(Entry.Name)
                    end
                end)
            end
        end

        --// Changes with the counts held of it and its materials, Luck, and
        --// the mobs known to drop it.
        local function GetSignature(Stock)
            local _, _, LuckPercent = Mobs.GetLuck()
            local Name = S.Selected
            local Parts = { tostring(Stock[Name] or 0), tostring(LuckPercent), tostring(#Assets:GetDroppedBy(Name)) }
            local Recipe = Assets:GetRecipe(Name)

            for _, Material in ipairs(Recipe and Recipe.Materials or {}) do
                table.insert(Parts, tostring(Stock[Material.Name] or 0))
            end

            return table.concat(Parts, "|")
        end

        ------------------------------------------------------------------------
        --// API
        ------------------------------------------------------------------------

        function Detail:Build(Parent)
            Theme = UI.Theme
            Scroll = Parent
        end

        function Detail:GetSelected()
            return S.Selected
        end

        --// Stock is the inventory (item -> count), read once by the caller.
        function Detail:Rebuild(Stock)
            if not Scroll then
                return
            end

            ClearChildren(Scroll)

            local Entry = S.Selected and Assets:Get(S.Selected)

            if not Entry then
                local Error = Assets.S.Error
                Note(Scroll, Error or "Pick an item on the left", 0, Error and Theme.Danger or nil)
                S.Signature = nil
                return
            end

            local Have = Stock[Entry.Name] or 0
            S.Signature = GetSignature(Stock)

            BuildHero(Entry, Have, 1)
            BuildTiles(Entry, 2)
            BuildValue(Entry, 3)
            BuildSources(Entry, Stock, 4)
            BuildUses(Entry, 5)
            BuildBars(Entry, 6)
            BuildTraits(Entry, 7)
            BuildActions(Entry, 9)
        end

        function Detail:Select(Name, Stock)
            S.Selected = Name
            Detail:Rebuild(Stock)
        end

        --// Rebuilt when the count held, Luck or the known drops changed.
        function Detail:Refresh(Stock)
            if not Scroll or not S.Selected then
                return
            end

            if GetSignature(Stock) ~= S.Signature then
                Detail:Rebuild(Stock)
            end
        end

        return Detail
    end,
}
]======],
	["Features/AssetDictionary.lua"] = [======[
-- AssetDictionary turns the game's assets (CoreCommons.getAssets, read by
-- SmithingRecipes) into one entry per item for the Asset Explorer
-- (AssetBrowser):
--
--   Entry = {
--       Name, Type (the asset's Value, "Other" when empty),
--       Stats = { { Key, Label, Value, Numeric } ... },  every value child
--       Worth, Flags = { Bound, Unobtainable, Badge, Pass, Group },
--       EventCurrency (the currency it is bought with, or nil),
--       Status = { Name, Props } or nil,
--   }
--
-- It also answers where an item comes from and goes: the recipe that makes
-- it, the recipes that use it, the mobs seen dropping it (MobDictionary),
-- and what the shop pays for it. Numbers are ranked against the other items
-- of the same type.
return {
    Name = "AssetDictionary",
    Dependencies = {"Runtime", "SmithingRecipes", "MobDictionary", "DetailKit"},

    Start = function(Context)
        local Recipes = Context.SmithingRecipes
        local Mobs = Context.MobDictionary
        local Kit = Context.DetailKit

        --// Children that are flags or shown on their own, not as stats.
        local FLAG_KEYS = { Bound = true, Unobtainable = true, Badge = true, Pass = true, Group = true }
        local SPECIAL_KEYS = { StatusEffect = true, EventCurrency = true, Worth = true }
        --// Stats an item's power is judged by, for the list bar.
        local POWER_KEYS = { "DMG", "DEF", "DEX" }
        --// The shop pays this share of Worth, or the second with the
        --// Agility pass. Items needing a pass, badge or group, or bought
        --// with an event currency, cannot be sold.
        local SELL_SHARE = 0.35
        local SELL_SHARE_AGILITY = 0.45

        local Dictionary = {
            Name = "AssetDictionary",
            SELL_SHARE = SELL_SHARE,
            SELL_SHARE_AGILITY = SELL_SHARE_AGILITY,
            S = {
                Entries = {},
                ByName = {},
                --// Type -> stat key -> { Max, Sorted (descending) }.
                Scales = {},
                Loaded = false,
                Error = nil,
            },
        }

        local S = Dictionary.S

        ------------------------------------------------------------------------
        --// Reading
        ------------------------------------------------------------------------

        local function SafeValue(Object)
            local Ok, Value = pcall(function()
                return Object.Value
            end)

            return Ok and Value or nil
        end

        --// Name -> { Value, Children } for every value child of an asset; an
        --// asset is an Instance, or a plain table of the same shape.
        local function ReadChildren(Asset)
            local Children = {}

            if typeof(Asset) == "Instance" then
                for _, Child in ipairs(Asset:GetChildren()) do
                    if Child:IsA("ValueBase") then
                        Children[Child.Name] = { Value = Child.Value, Children = ReadChildren(Child) }
                    end
                end
            elseif type(Asset) == "table" then
                for Name, Child in pairs(Asset) do
                    if type(Name) == "string" and Name ~= "Value" and type(Child) == "table" then
                        Children[Name] = { Value = Child.Value, Children = ReadChildren(Child) }
                    end
                end
            end

            return Children
        end

        local function ReadStatus(Child)
            local Effect = Child and Child.Value

            if Effect == nil or Effect == false or Effect == "" or string.lower(tostring(Effect)) == "none" then
                return nil
            end

            local Status = { Name = tostring(Effect), Props = {} }

            for Name, Prop in pairs(Child.Children) do
                table.insert(Status.Props, { Label = Kit.Prettify(Name), Value = Prop.Value })
            end

            table.sort(Status.Props, function(A, B)
                return A.Label < B.Label
            end)

            return Status
        end

        local function ReadEntry(Name, Asset)
            local Type = SafeValue(Asset)
            Type = Type ~= nil and tostring(Type) or ""

            local Children = ReadChildren(Asset)
            local Entry = {
                Name = Name,
                Type = Type ~= "" and Type or Recipes.UNKNOWN_TYPE,
                Stats = {},
                Flags = {},
                Worth = tonumber(Children.Worth and Children.Worth.Value),
                EventCurrency = Children.EventCurrency and tostring(Children.EventCurrency.Value) or nil,
                Status = ReadStatus(Children.StatusEffect),
            }

            for Key, Child in pairs(Children) do
                if FLAG_KEYS[Key] then
                    Entry.Flags[Key] = true
                elseif not SPECIAL_KEYS[Key] and Child.Value ~= nil then
                    table.insert(Entry.Stats, {
                        Key = Key,
                        Label = Kit.Prettify(Key),
                        Value = Child.Value,
                        Numeric = type(Child.Value) == "number",
                    })
                end
            end

            table.sort(Entry.Stats, function(A, B)
                return A.Label < B.Label
            end)

            return Entry
        end

        function Dictionary.GetStat(Entry, Key)
            for _, Stat in ipairs(Entry.Stats) do
                if Stat.Key == Key then
                    return Stat.Value
                end
            end

            return nil
        end

        --// Level, else the skill it needs, for sorting and the list.
        function Dictionary.GetLevel(Entry)
            local Level = Dictionary.GetStat(Entry, "LVL")

            if type(Level) == "number" then
                return Level, "LV"
            end

            local Skill = Dictionary.GetStat(Entry, "Skill")
            return type(Skill) == "number" and Skill or nil, "SKILL"
        end

        ------------------------------------------------------------------------
        --// Ranking within a type
        ------------------------------------------------------------------------

        local function BuildScales()
            local Values = {}

            for _, Entry in ipairs(S.Entries) do
                Values[Entry.Type] = Values[Entry.Type] or {}

                local Numbers = {}

                for _, Stat in ipairs(Entry.Stats) do
                    if Stat.Numeric then
                        Numbers[Stat.Key] = Stat.Value
                    end
                end

                Numbers.Worth = Entry.Worth

                for Key, Value in pairs(Numbers) do
                    Values[Entry.Type][Key] = Values[Entry.Type][Key] or {}
                    table.insert(Values[Entry.Type][Key], Value)
                end
            end

            S.Scales = {}

            for Type, Keys in pairs(Values) do
                S.Scales[Type] = {}

                for Key, List in pairs(Keys) do
                    table.sort(List, function(A, B)
                        return A > B
                    end)

                    S.Scales[Type][Key] = { Max = List[1], Sorted = List }
                end
            end
        end

        --// Fraction of the highest Value among the items of Type with this
        --// stat (0..1), its rank (1 = highest) and how many have it.
        function Dictionary.GetScale(Type, Key, Value)
            local Scales = S.Scales[Type]
            local Scale = Scales and Scales[Key]

            if not Scale or type(Value) ~= "number" then
                return 0, nil, 0
            end

            local Fraction = Scale.Max > 0 and math.clamp(Value / Scale.Max, 0, 1) or 0
            return Fraction, table.find(Scale.Sorted, Value), #Scale.Sorted
        end

        --// 0..1: the best of DMG / DEF / DEX against its type, or nil when
        --// it has none of them.
        function Dictionary.GetPower(Entry)
            local Best = nil

            for _, Key in ipairs(POWER_KEYS) do
                local Value = Dictionary.GetStat(Entry, Key)

                if type(Value) == "number" then
                    Best = math.max(Best or 0, (Dictionary.GetScale(Entry.Type, Key, Value)))
                end
            end

            return Best
        end

        --// "WEAPON  ·  LV 20  ·  DMG 45  ·  DEX 3".
        function Dictionary.Summarize(Entry)
            local Parts = { string.upper(Entry.Type) }
            local Level, LevelKind = Dictionary.GetLevel(Entry)

            if Level then
                table.insert(Parts, LevelKind .. " " .. Kit.FormatNumber(Level))
            end

            for _, Key in ipairs(POWER_KEYS) do
                local Value = Dictionary.GetStat(Entry, Key)

                if type(Value) == "number" then
                    table.insert(Parts, Key .. " " .. Kit.FormatNumber(Value))
                end
            end

            return table.concat(Parts, "  ·  ")
        end

        ------------------------------------------------------------------------
        --// Load
        ------------------------------------------------------------------------

        --// Reads the assets again. False (and S.Error) when they cannot be
        --// read right now.
        function Dictionary:Load()
            local Assets = Recipes:GetAssets()

            if type(Assets) ~= "table" then
                S.Error = "The game's assets cannot be read right now. Press RELOAD to try again."
                return false
            end

            local Entries, ByName = {}, {}

            for Name, Asset in pairs(Assets) do
                if type(Name) == "string" and (typeof(Asset) == "Instance" or type(Asset) == "table") then
                    local Entry = ReadEntry(Name, Asset)
                    table.insert(Entries, Entry)
                    ByName[Name] = Entry
                end
            end

            --// By type, then level (or skill), then name.
            table.sort(Entries, function(A, B)
                if A.Type ~= B.Type then
                    return A.Type < B.Type
                end

                local LevelA = Dictionary.GetLevel(A) or 0
                local LevelB = Dictionary.GetLevel(B) or 0

                if LevelA ~= LevelB then
                    return LevelA < LevelB
                end

                return A.Name < B.Name
            end)

            S.Entries = Entries
            S.ByName = ByName
            S.Error = nil
            S.Loaded = true
            BuildScales()

            --// Fixed for the load, and wanted for every list row.
            for _, Entry in ipairs(Entries) do
                Entry.Power = Dictionary.GetPower(Entry)
                Entry.Summary = Dictionary.Summarize(Entry)
            end

            return true
        end

        function Dictionary:GetAll()
            return S.Entries
        end

        function Dictionary:Get(Name)
            return S.ByName[Name]
        end

        ------------------------------------------------------------------------
        --// Where an item comes from and goes
        ------------------------------------------------------------------------

        --// The recipe that makes Name, or nil.
        function Dictionary:GetRecipe(Name)
            return Recipes:Get(Name)
        end

        --// Recipes using Name as a material: { { Recipe, Amount } ... }.
        function Dictionary:GetUses(Name)
            local Uses = {}

            for _, Recipe in ipairs(Recipes:GetAll()) do
                for _, Material in ipairs(Recipe.Materials) do
                    if Material.Name == Name then
                        table.insert(Uses, { Recipe = Recipe, Amount = Material.Amount })
                    end
                end
            end

            return Uses
        end

        --// Mobs seen (this run or saved) that drop Name, best chance first:
        --// { { Mob, Chance (with Luck), Drop } ... }.
        function Dictionary:GetDroppedBy(Name)
            local _, _, LuckPercent = Mobs.GetLuck()
            local Sources = {}

            for MobName, Drops in pairs(Mobs.S.Drops) do
                for _, Drop in ipairs(Drops) do
                    if Drop.Name == Name then
                        table.insert(Sources, {
                            Mob = MobName,
                            Drop = Drop,
                            Chance = (Mobs.GetDropOdds(Drop, LuckPercent)),
                        })
                    end
                end
            end

            table.sort(Sources, function(A, B)
                if A.Chance ~= B.Chance then
                    return A.Chance > B.Chance
                end

                return A.Mob < B.Mob
            end)

            return Sources
        end

        --// What the shop pays for one: { Normal, Agility }, or nil when it
        --// cannot be sold there.
        function Dictionary.GetSellPrice(Entry)
            local Flags = Entry.Flags

            if not Entry.Worth or Flags.Pass or Flags.Badge or Flags.Group or Entry.EventCurrency then
                return nil
            end

            return {
                Normal = math.floor(Entry.Worth * SELL_SHARE),
                Agility = math.floor(Entry.Worth * SELL_SHARE_AGILITY),
            }
        end

        --// How many the inventory holds.
        function Dictionary:GetHave(Name)
            return Recipes:GetInventory()[Name] or 0
        end

        return Dictionary
    end,
}
